export async function chat(messages: unknown[], schema: unknown) {
  return fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    body: JSON.stringify({ model: "gpt-4o-mini", messages, functions: [{ name: "get_order", parameters: schema }], function_call: "auto" }),
  });
}
